import {makeObject,disposeObject} from './objects.js';
import * as T from './three.module.js';
export function createEffects(scene){
 const max=1400,p=new Float32Array(max*3),col=new Float32Array(max*3),slots=Array.from({length:max},()=>({life:0}));let cursor=0;
 const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(p,3));g.setAttribute('color',new T.BufferAttribute(col,3));
 const cv=document.createElement('canvas');cv.width=cv.height=32;let ctx=cv.getContext('2d'),grad=ctx.createRadialGradient(16,16,0,16,16,16);grad.addColorStop(0,'#fff');grad.addColorStop(.25,'#fff');grad.addColorStop(1,'#fff0');ctx.fillStyle=grad;ctx.fillRect(0,0,32,32);const tex=new T.CanvasTexture(cv);
 const points=new T.Points(g,new T.PointsMaterial({size:.15,map:tex,transparent:true,vertexColors:true,depthWrite:false,blending:T.AdditiveBlending}));points.frustumCulled=false;scene.add(points);
 const trails=new Float32Array(max*6),trailcol=new Float32Array(max*6),lg=new T.BufferGeometry();lg.setAttribute('position',new T.BufferAttribute(trails,3));lg.setAttribute('color',new T.BufferAttribute(trailcol,3));const lines=new T.LineSegments(lg,new T.LineBasicMaterial({vertexColors:true,transparent:true,opacity:.75,depthWrite:false}));lines.frustumCulled=false;scene.add(lines);
 function firework(x=0,y=6,z=1){let colors=['#ee895c','#bfe6b9','#f5c461','#edf0ce','#c8b1e5'],c=new T.Color(colors[Math.floor(Math.random()*colors.length)]);for(let i=0;i<110;i++){const s=slots[cursor++%max],a=Math.random()*Math.PI*2,v=.8+Math.random()*2.6,u=Math.random()*2-1,r=Math.sqrt(1-u*u);Object.assign(s,{life:1.15+Math.random()*.8,max:2,x,y,z,vx:Math.cos(a)*r*v,vy:u*v,vz:Math.sin(a)*r*v*.4,c})}}
 function update(dt){for(let i=0;i<max;i++){let s=slots[i],j=i*3,k=i*6;if(s.life>0){s.life-=dt;s.vy-=dt*1.2;s.x+=s.vx*dt;s.y+=s.vy*dt;s.z+=s.vz*dt;let fade=Math.max(0,s.life/2);p[j]=s.x;p[j+1]=s.y;p[j+2]=s.z;col[j]=s.c.r*fade;col[j+1]=s.c.g*fade;col[j+2]=s.c.b*fade;trails[k]=s.x;trails[k+1]=s.y;trails[k+2]=s.z;trails[k+3]=s.x-s.vx*.14;trails[k+4]=s.y-s.vy*.14;trails[k+5]=s.z-s.vz*.14;for(let a=0;a<6;a++)trailcol[k+a]=col[j+a%3]*(a<3?.8:.2)}else{p[j]=p[j+1]=p[j+2]=-100;for(let a=0;a<6;a++)trails[k+a]=-100}}g.attributes.position.needsUpdate=g.attributes.color.needsUpdate=lg.attributes.position.needsUpdate=lg.attributes.color.needsUpdate=true}
 return {firework,update};
}
export function createFind(scene){const group=new T.Group();scene.add(group);let object=null;group.visible=false;return {group,set(item){if(object)disposeObject(object);object=item.type==='object'?makeObject(item):new T.Mesh(new T.BoxGeometry(1.25,.9,.035),new T.MeshStandardMaterial({color:item.type==='coupon'?'#f4d583':item.type==='postcard'?'#f1bfaa':'#fff6de'}));group.add(object)},update(t){group.visible=true;group.position.set(0,3.1+Math.sin(Math.min(1,t)*Math.PI*.7)*2.2,Math.min(1,t)*2);group.rotation.set(-.15,t*3,Math.sin(t*4)*.14);group.scale.setScalar(.3+Math.min(t,1)*1.2);object.userData.animate?.(t)}}}
export function icon(type='map'){
 const start='<svg viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg" fill="none" stroke="#49614d" stroke-width="3" stroke-linejoin="round">',end='</svg>';
 const paths={map:'<path d="M13 27L44 17 77 29 107 19V94L77 105 44 93 13 104Z" fill="#f2e8c9"/><path d="M44 17V93M77 29V105" stroke="#c7b690"/><path d="M27 74Q46 38 61 64T94 52" stroke="#bf7855" stroke-dasharray="5 4"/><path d="M57 34a11 11 0 1122 0c0 9-11 19-11 19S57 43 57 34Z" fill="#bf7855"/><circle cx="68" cy="34" r="3" fill="#fff"/>',bottle:'<path d="M49 9H71V35L83 49V105Q60 112 37 105V49L49 35Z" fill="#a0b294"/><path d="M48 8H72V22H48Z" fill="#d7a25f"/><path d="M37 59H83V91H37Z" fill="#fff4d5"/><text x="60" y="78" text-anchor="middle" font-size="10" fill="#4a624f" stroke="none">СПОТЫКАЧ</text>',camera:'<path d="M12 35H36L42 23H73L79 35H107V98H12Z" fill="#a6b4a0"/><circle cx="61" cy="65" r="24" fill="#eee2c0"/><circle cx="61" cy="65" r="14" fill="#678575"/><path d="M87 46H99M20 23L15 11M28 23L31 9" stroke="#bf7855"/>',ticket:'<path d="M10 30H110V47Q94 60 110 73V91H10V74Q26 60 10 46Z" fill="#eac57d"/><path d="M79 30V91" stroke-dasharray="4 4"/><path d="M28 48H63M28 62H58M28 76H66"/>',magnet:'<path d="M28 24H48V70Q60 91 72 70V24H92V70C92 115 28 115 28 70Z" fill="#bd755a"/><path d="M28 24H48V46H28ZM72 24H92V46H72Z" fill="#d8ddcb"/>',statue:'<path d="M29 103H92V92H29Z" fill="#bcac8a"/><path d="M43 92L46 59 37 48 53 33 75 42 83 64 70 73 79 92Z" fill="#d6c29b"/><path d="M53 33L44 17 59 22 75 10 75 42"/><circle cx="62" cy="45" r="3" fill="#49614d"/>',compass:'<circle cx="60" cy="65" r="40" fill="#e6d29b"/><circle cx="60" cy="65" r="31" fill="#fff6dd"/><path d="M75 43L66 73 46 87 54 57Z" fill="#c77655"/><path d="M55 25V13H65V25"/>',mystery:'<path d="M20 44L60 24 100 44V98L60 114 20 98Z" fill="#d0ba95"/><path d="M20 44L60 63 100 44M60 63V114"/><text x="60" y="86" fill="#6d775d" stroke="none" font-size="30" text-anchor="middle">?</text>'};return start+(paths[type]||paths.map)+end;
}
